class ConditionalI18nExtension(Extension):
    tags = {"ctrans"}

    def __init__(self, environment):
        super().__init__(environment)
        self.environment.install_gettext_translations(self._install)

    def _install(self, translations):
        self.environment.install_gettext_translations(translations)

def _make_conditional_node(self, condition, variables, content, plural_content, fallback):
    if condition:
        return self.environment.gettext(content)
    else:
        return fallback

def parse(self, parser):
    condition = parser.parse_expression()
    variables = {}
    while parser.stream.current.type != 'block_end':
        if parser.stream.current.type == 'comma':
            next(parser.stream)
        token = parser.stream.current
        if token.value in variables:
            parser.fail(f'Variable {token.value} defined twice.', token.lineno)
        if parser.stream.current.type == 'assign':
            next(parser.stream)
            variables[token.value] = parser.parse_expression()
        else:
            variables[token.value] = nodes.Name(token.value, 'load')
    parser.stream.expect('block_end')
    content = self._parse_block(parser, True)
    plural_content = None
    if parser.stream.current.test('name:pluralize'):
        next(parser.stream)
        plural_content = self._parse_block(parser, False)
    fallback = parser.parse_expression()
    return self._make_conditional_node(condition, variables, content, plural_content, fallback)
```

